<?php use App\Core\Format;$slug=$tenant['slug'];$headers=['evento'=>'Evento','fase'=>'Fase','documento'=>'Documento / Arquivo','secretaria'=>'Secretaria','responsavel'=>'Responsável','perfil'=>'Perfil','data'=>'Data / Hora','origem'=>'Origem','detalhamento'=>'Detalhamento'];$base=['fase'=>$phase?:null,'tipo'=>$type?:null];?>
<div class="module-page"><div class="module-hero"><div><h1><?=$scope==='secretaria'?'Meu Histórico':'Histórico'?></h1><p><?=$scope==='stratelli'?'Rastreabilidade completa das movimentações de documentos, modelos, validações e cronograma desta instância.':($scope==='municipio'?'Histórico das movimentações municipais e das secretarias.':'Histórico restrito às movimentações dos documentos da sua secretaria.')?></p></div><span class="module-context">◷ Auditoria por perfil</span></div>
<div class="module-kpis-grid"><div class="module-kpi"><small>MOVIMENTAÇÕES</small><b><?=$summary['total']?></b><span>No filtro atual</span></div><div class="module-kpi"><small>ENVIOS / SUBSTITUIÇÕES</small><b><?=$summary['envios']?></b><span>Arquivos recebidos</span></div><div class="module-kpi success"><small>APROVAÇÕES</small><b><?=$summary['aprovacoes']?></b><span>Validações concluídas</span></div><div class="module-kpi warning"><small>CORREÇÕES</small><b><?=$summary['correcoes']?></b><span>Solicitações registradas</span></div><div class="module-kpi neutral"><small>MODELOS</small><b><?=$summary['modelos']?></b><span>Movimentações de modelo</span></div></div>
<section class="card history-card"><form method="get" action="/<?=Format::h($slug)?>/historico" class="history-filter"><label>Fase<select name="fase"><option value="0">Todas as fases</option><?php foreach($fasesVisiveis as$f):?><option value="<?=$f['id']?>" <?=((int)$phase===(int)$f['id'])?'selected':''?>>Fase <?=Format::h($f['ordem'])?> — <?=Format::h($f['aba'])?></option><?php endforeach;?></select></label><label>Movimentação<select name="tipo"><option value="">Todas</option><?php foreach(['enviado'=>'Envios','aprovado'=>'Aprovações','correção'=>'Correções','modelo'=>'Modelos','fase'=>'Fases']as$v=>$label):?><option value="<?=Format::h($v)?>" <?=$type===$v?'selected':''?>><?=Format::h($label)?></option><?php endforeach;?></select></label><button class="btn primary">Filtrar</button><a class="btn neutral" href="/<?=Format::h($slug)?>/historico">Limpar</a></form>
<div class="table-scroll"><table class="history-table sortable-history"><thead><tr><?php foreach($headers as$key=>$label):$next=($sort===$key&&$dir==='asc')?'desc':'asc';$q=array_filter(['fase'=>$phase?:null,'tipo'=>$type?:null,'ordem'=>$key,'direcao'=>$next]);?><th><a class="history-sort-link <?=$sort===$key?'active':''?>" href="/<?=Format::h($slug)?>/historico?<?=http_build_query($q)?>"><?=Format::h($label)?> <span><?=$sort===$key?($dir==='asc'?'▲':'▼'):'↕'?></span></a></th><?php endforeach;?><th>Ação</th></tr></thead><tbody><?php if($items):foreach($items as$h):?><tr><td><b><?=Format::h($h['evento'])?></b><br><small><?=Format::h($h['status']?:'—')?></small></td><td><?php if($h['fase_ordem']!==null):?><b>Fase <?=Format::h($h['fase_ordem'])?></b><br><small><?=Format::h($h['fase_aba'])?></small><?php else:?>—<?php endif;?></td><td><b><?=Format::h($h['documento']?:$h['arquivo_original']?:'—')?></b><?php if($h['arquivo_original']&&$h['documento']):?><br><small><?=Format::h($h['arquivo_original'])?></small><?php endif;?><?php if(!empty($h['versao'])||!empty($h['checksum_sha256'])):?><div class="history-file-audit"><?php if(!empty($h['versao'])):?><span>v<?=Format::h($h['versao'])?></span><?php endif;?><?php if(!empty($h['mime_type'])):?><span><?=Format::h($h['mime_type'])?></span><?php endif;?><?php if(!empty($h['tamanho'])):?><span><?=Format::h(Format::fileSize((int)$h['tamanho']))?></span><?php endif;?><?php if(!empty($h['checksum_sha256'])):?><code title="<?=Format::h($h['checksum_sha256'])?>">SHA-256 <?=Format::h(substr($h['checksum_sha256'],0,12))?>…</code><?php endif;?></div><?php endif;?></td><td><?=Format::h(($h['secretaria_sigla']?$h['secretaria_sigla'].' — ':'').($h['secretaria_nome']?:'—'))?></td><td><b><?=Format::h($h['usuario_nome']?:'Sistema')?></b><br><small><?=Format::h($h['usuario_email']?:'—')?></small></td><td><?=Format::h(!empty($h['administrador_plataforma'])?'STRATELLI':($h['usuario_grupo']?:'SISTEMA'))?></td><td><?=Format::h(Format::dateTime($h['criado_em']))?></td><td><b><?=Format::h($h['ip']?:'—')?></b><?php if(!empty($h['user_agent'])):?><br><small title="<?=Format::h($h['user_agent'])?>"><?=Format::h(str_contains($h['user_agent'],'Edg/')?'Edge':(str_contains($h['user_agent'],'Chrome/')?'Chrome':(str_contains($h['user_agent'],'Firefox/')?'Firefox':(str_contains($h['user_agent'],'Safari/')?'Safari':'Navegador'))))?></small><?php endif;?></td><td><?=Format::h($h['motivo']?:'—')?></td><td><?php if($h['arquivo_salvo']):?><a class="mini-link" href="/<?=Format::h($slug)?>/arquivos/historico/<?=$h['id']?>">Baixar</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;else:?><tr><td colspan="10"><div class="empty-state">Nenhuma movimentação encontrada para os filtros selecionados.</div></td></tr><?php endif;?></tbody></table></div>
<div class="history-pagination"><div class="history-pagination-info"><?=$total?'Exibindo '.($start+1).' a '.min($start+$perPage,$total).' de '.$total.' registros':'Nenhum registro'?> · Página <?=$page?> de <?=$pages?></div><nav class="history-pagination-nav"><?php $common=array_filter(['fase'=>$phase?:null,'tipo'=>$type?:null,'ordem'=>$sort,'direcao'=>$dir]);if($page>1):?><a class="history-page-link" href="/<?=Format::h($slug)?>/historico?<?=http_build_query($common+['pagina'=>$page-1])?>">‹ Anterior</a><?php else:?><span class="history-page-disabled">‹ Anterior</span><?php endif;?><?php $prev=0;foreach($visible as$p):if($prev&&$p>$prev+1):?><span class="history-page-ellipsis">…</span><?php endif;?><?php if($p===$page):?><span class="history-page-current"><?=$p?></span><?php else:?><a class="history-page-link" href="/<?=Format::h($slug)?>/historico?<?=http_build_query($common+['pagina'=>$p])?>"><?=$p?></a><?php endif;?><?php $prev=$p;endforeach;?><?php if($page<$pages):?><a class="history-page-link" href="/<?=Format::h($slug)?>/historico?<?=http_build_query($common+['pagina'=>$page+1])?>">Próxima ›</a><?php else:?><span class="history-page-disabled">Próxima ›</span><?php endif;?></nav></div>
</section></div>
